): Promise<void> {
  const label = isHeartbeat ? 'Heartbeat' : 'Tier 1';
  console.log(`[HealthMonitor] ${label} starting — ${cycleTime}`);
  const t0 = performance.now();

  let checks: CheckResult[];
  try {
    checks = await runAllChecks();
