const DEBOUNCE_MS = 5 * 60 * 1000;
const sent = new Map<string, number>();

export async function sendAlert(
  service: string,
  level: 'critical' | 'warning',
  message: string,
  error?: unknown,
): Promise<void> {
  const token = process.env.TELEGRAM_BOT_TOKEN;
  const chatId = process.env.TELEGRAM_CHAT_ID;
  if (!token || !chatId) return;

  const key = `${service}:${message.slice(0, 60)}`;
  const now = Date.now();
  if ((sent.get(key) ?? 0) + DEBOUNCE_MS > now) return;
  sent.set(key, now);

  const icon = level === 'critical' ? '\u{1F534}' : '⚠️';
  const errorSnippet = error ? `\n\`${String(error).slice(0, 300)}\`` : '';
  const text = `${icon} *airways.gg — ${service}*\n${message}${errorSnippet}`;

  await fetch(`https://api.telegram.org/bot${token}/sendMessage`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ chat_id: chatId, text, parse_mode: 'Markdown' }),
  }).catch(() => {});
}

import { json, error } from '@sveltejs/kit';
import type { RequestHandler } from './$types';
import { getDb } from '$lib/server/db';
import { pushSubscriptions } from '$lib/server/db';
import { eq, and } from 'drizzle-orm';

export const GET: RequestHandler = async ({ params, url }) => {
  const flightId = parseInt(params.flightId, 10);
  if (isNaN(flightId)) throw error(400, 'Invalid flightId');

  const endpoint = url.searchParams.get('endpoint');
  if (!endpoint) throw error(400, 'Missing endpoint');

  const db = getDb();
  const rows = await db
    .select({ id: pushSubscriptions.id })
    .from(pushSubscriptions)
    .where(and(eq(pushSubscriptions.flightId, flightId), eq(pushSubscriptions.endpoint, endpoint)))
    .limit(1);

  return json({ subscribed: rows.length > 0 });
};

